(2307153, 316960, 51802, '<td valign="top">I''m pretty sure this is bronze.</td>', 'I''m pretty sure this is bronze.', '2006-04-12 14:15:09.000000', NULL, 1),
(2307162, 318262, 51802, '<td valign="top">Very nice shot!  I really like how the DOF and the background complement this shot.  Only thing keeping me from giving this a 10 is the sand stuck to the side of the ring.  Its distracting and doesn''t follow the smooth flow of the ring and clean lines of the sand hill.</td>', 'Very nice shot!  I really like how the DOF and the background complement this shot.  Only thing keeping me from giving this a 10 is the sand stuck to the side of the ring.  Its distracting and doesn''t follow the smooth flow of the ring and clean lines of the sand hill.', '2006-04-12 14:18:28.000000', NULL, 1),
(2307168, 319141, 44490, '<td valign="top">Interesting reflection, nice color.  Seems more about the reflection than about the chrome, which might hurt your score for this challenge.</td>', 'Interesting reflection, nice color.  Seems more about the reflection than about the chrome, which might hurt your score for this challenge.', '2006-04-12 14:19:09.000000', NULL, 1),
(2307169, 316992, 51802, '<td valign="top">Sorry,  I don''t see how chrome is the main subject of this shot.</td>', 'Sorry,  I don''t see how chrome is the main subject of this shot.', '2006-04-12 14:20:01.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2307172, 318838, 51802, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2006-04-12 14:20:56.000000', NULL, 1),
(2307181, 319193, 51802, '<td valign="top">I think this would be much more dramatic if the sun were reflected in the sphere instead of shining over it.  The bright sun has caused the rest of the shot to be under exposed.</td>', 'I think this would be much more dramatic if the sun were reflected in the sphere instead of shining over it.  The bright sun has caused the rest of the shot to be under exposed.', '2006-04-12 14:22:50.000000', NULL, 1),
(2307184, 319748, 51802, '<td valign="top">Simple and elegant.  I like it.</td>', 'Simple and elegant.  I like it.', '2006-04-12 14:23:53.000000', NULL, 1),
(2307185, 318671, 51802, '<td valign="top">Great perspective.  The reflection is a wonderful enhancement!</td>', 'Great perspective.  The reflection is a wonderful enhancement!', '2006-04-12 14:24:41.000000', NULL, 1),
(2307191, 319265, 51802, '<td valign="top">There is a lot of noise in this shot and no clear focal point.  My eye does not find a place to rest in this shot.</td>', 'There is a lot of noise in this shot and no clear focal point.  My eye does not find a place to rest in this shot.', '2006-04-12 14:26:33.000000', NULL, 1),
(2307197, 319655, 44490, '<td valign="top">Nice display and colors.  It''s probably more gold, silver, etc. than chrome, which might cost a point.  Background is distracting, try your fastest lens at largest aperture to blur out the background more.</td>', 'Nice display and colors.  It''s probably more gold, silver, etc. than chrome, which might cost a point.  Background is distracting, try your fastest lens at largest aperture to blur out the background more.', '2006-04-12 14:28:27.000000', NULL, 1),
(2307205, 319788, 44490, '<td valign="top">Nice box.  Less straight-on and less-central composition and larger image would be better, please see <a href="//www.dpchallenge.com/tutorial.php?TUTORIAL_ID=26" rel="nofollow" target="_blank">tutorial</a></td>', 'Nice box.  Less straight-on and less-central composition and larger image would be better, please see tutorial', '2006-04-12 14:31:26.000000', NULL, 1),
(2307212, 316992, 44490, '<td valign="top">Nice arrangement.  Looks more like crystal than chrome.  Overall image is dark, more exposure and lighting of the flower heads would be better, allowing the yellows to be featured nicely.</td>', 'Nice arrangement.  Looks more like crystal than chrome.  Overall image is dark, more exposure and lighting of the flower heads would be better, allowing the yellows to be featured nicely.', '2006-04-12 14:34:21.000000', NULL, 1),
(2307215, 319893, 44490, '<td valign="top">Nice composition.  Better lighting would help, especially on lower part of image.</td>', 'Nice composition.  Better lighting would help, especially on lower part of image.', '2006-04-12 14:36:07.000000', NULL, 1),
(2307243, 318539, 44490, '<td valign="top">Nice composition, colors.  Image seems to low key or underexposed, at least slightly brighter levels would be better, so that more detail can be seen.</td>', 'Nice composition, colors.  Image seems to low key or underexposed, at least slightly brighter levels would be better, so that more detail can be seen.', '2006-04-12 14:44:27.000000', NULL, 1),
(2307251, 319524, 44490, '<td valign="top">Nice composition.  Overall image seems pretty dull for chrome, I''d prefer brighter levels and more contrast.</td>', 'Nice composition.  Overall image seems pretty dull for chrome, I''d prefer brighter levels and more contrast.', '2006-04-12 14:47:16.000000', NULL, 1),
(2307260, 318675, 44490, '<td valign="top">Nice idea.  Overall image is too dark, also causing background to seem cluttered, as I''m looking for something clearly visible.  Wish it were easier to read CHROME on the bottle, better illumination would help.</td>', 'Nice idea.  Overall image is too dark, also causing background to seem cluttered, as I''m looking for something clearly visible.  Wish it were easier to read CHROME on the bottle, better illumination would help.', '2006-04-12 14:51:02.000000', NULL, 1),
(2307261, 319310, 29177, '<td valign="top">Wish you would have done this with out the orange... but I still like it alot! Well done... good luck!</td>', 'Wish you would have done this with out the orange... but I still like it alot! Well done... good luck!', '2006-04-12 14:52:10.000000', NULL, 1),
(2307267, 319874, 44490, '<td valign="top">Nice composition.  Doesn''t look like these clippers ever had a chrome finish, clearer evidence would have at least something really shiny.</td>', 'Nice composition.  Doesn''t look like these clippers ever had a chrome finish, clearer evidence would have at least something really shiny.', '2006-04-12 14:54:06.000000', NULL, 1),
(2307268, 320047, 43594, '<td valign="top">COOL!!!</td>', 'COOL!!!', '2006-04-12 14:54:37.000000', NULL, 1),
(2307276, 319868, 44490, '<td valign="top">Nice bike and nice reflected sunset.  Unfortunately, the bike is in the shadows -- for this challenge, its chrome should be featured.  So bump the levels to feature the bike, the sunset is secondary.</td>', 'Nice bike and nice reflected sunset.  Unfortunately, the bike is in the shadows -- for this challenge, its chrome should be featured.  So bump the levels to feature the bike, the sunset is secondary.', '2006-04-12 14:56:45.000000', NULL, 1),
(2307309, 319193, 44490, '<td valign="top">Nice idea.  But in your efforts to include the sun, you underexposed badly, so that it''s difficult to make out the nice reflections.  You might be able to rescue this with level adjustment upwards.</td>', 'Nice idea.  But in your efforts to include the sun, you underexposed badly, so that it''s difficult to make out the nice reflections.  You might be able to rescue this with level adjustment upwards.', '2006-04-12 15:06:53.000000', NULL, 1),
(2307346, 319604, 44490, '<td valign="top">Nice car, lines, shapes.  Overall image feels dark/gray.  Please revisit your levels after conversion to B&amp;W.</td>', 'Nice car, lines, shapes.  Overall image feels dark/gray.  Please revisit your levels after conversion to B&W.', '2006-04-12 15:16:40.000000', NULL, 1),
(2307358, 317861, 49652, '<td valign="top">I''m guessing this is the Jump entry put in the wrong challenge.   Good, high jump.</td>', 'I''m guessing this is the Jump entry put in the wrong challenge.   Good, high jump.', '2006-04-12 15:20:08.000000', NULL, 1),
(2307368, 319943, 44490, '<td valign="top">Nice portrait, eyes, tones.  Wish you had a slightly lower angle to catch more of a reflection of his face in the chrome.</td>', 'Nice portrait, eyes, tones.  Wish you had a slightly lower angle to catch more of a reflection of his face in the chrome.', '2006-04-12 15:21:58.000000', NULL, 1),
(2307377, 318092, 44490, '<td valign="top">Nice idea.  Please revisit your levels after conversion to B&amp;W, wish for brighter levels, as overall image seems dark.</td>', 'Nice idea.  Please revisit your levels after conversion to B&W, wish for brighter levels, as overall image seems dark.', '2006-04-12 15:23:45.000000', NULL, 1),
(2307392, 318071, 44490, '<td valign="top">Nice idea, composition.  I think that more DOF would be better, as the chrome dominates nicely both by shine and position.  More illumination from the front might also help.</td>', 'Nice idea, composition.  I think that more DOF would be better, as the chrome dominates nicely both by shine and position.  More illumination from the front might also help.', '2006-04-12 15:27:54.000000', NULL, 1),
(2307421, 319777, 44490, '<td valign="top">Nice idea and arrangement, made me smile.  Wish leaves in background were less diestracting, maybe a lower angle would be better.</td>', 'Nice idea and arrangement, made me smile.  Wish leaves in background were less diestracting, maybe a lower angle would be better.', '2006-04-12 15:35:10.000000', NULL, 1),
(2307431, 319580, 44490, '<td valign="top">Nice ''n simple.  There''s somewhat too much "negative" space, I''d prefer a tighter crop.</td>', 'Nice ''n simple.  There''s somewhat too much "negative" space, I''d prefer a tighter crop.', '2006-04-12 15:37:30.000000', NULL, 1),
(2307432, 320047, 43936, '<td valign="top">Wow! Love it!</td>', 'Wow! Love it!', '2006-04-12 15:37:44.000000', NULL, 1),
(2307444, 319666, 43936, '<td valign="top">Hard stuff... Hmm... I like that!</td>', 'Hard stuff... Hmm... I like that!', '2006-04-12 15:40:24.000000', NULL, 1),
(2307451, 319110, 33515, '<td valign="top">I think I would have liked this better if the cup was fill, not showing the dried foam. Well composed.</td>', 'I think I would have liked this better if the cup was fill, not showing the dried foam. Well composed.', '2006-04-12 15:41:48.000000', NULL, 1),
(2307454, 319281, 43936, '<td valign="top">This is just great! Gets your attention right away and keeps you looking....</td>', 'This is just great! Gets your attention right away and keeps you looking....', '2006-04-12 15:42:39.000000', NULL, 1),
(2307458, 319604, 33515, '<td valign="top">The B&amp;W makes it harder to pick up on the chrome aspect of the photo.</td>', 'The B&W makes it harder to pick up on the chrome aspect of the photo.', '2006-04-12 15:43:29.000000', NULL, 1),
(2307459, 318715, 44490, '<td valign="top">Nice composition, colors.  Lovely matching rust and dirt colors, but wish for more chrome look/feel for this challenge.</td>', 'Nice composition, colors.  Lovely matching rust and dirt colors, but wish for more chrome look/feel for this challenge.', '2006-04-12 15:43:29.000000', NULL, 1),
(2307463, 319281, 33515, '<td valign="top">Great picture, I would think in color the chrome would have come across stronger.</td>', 'Great picture, I would think in color the chrome would have come across stronger.', '2006-04-12 15:44:19.000000', NULL, 1),
(2307469, 317979, 44490, '<td valign="top">Nice idea and arrangement.  Sharper/clearer would be better, I want to make out more detail in the buds.</td>', 'Nice idea and arrangement.  Sharper/clearer would be better, I want to make out more detail in the buds.', '2006-04-12 15:46:17.000000', NULL, 1),
(2307470, 319080, 43936, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2006-04-12 15:47:12.000000', NULL, 1),
(2307471, 319894, 33515, '<td valign="top">Very nice, the ripples draw you in.</td>', 'Very nice, the ripples draw you in.', '2006-04-12 15:47:13.000000', NULL, 1),
(2307475, 317533, 44490, '<td valign="top">Nice lure.  Wish you had a real fish attached to it, I think that that would have really made the shot.</td>', 'Nice lure.  Wish you had a real fish attached to it, I think that that would have really made the shot.', '2006-04-12 15:47:33.000000', NULL, 1),
(2307496, 319692, 44490, '<td valign="top">Nice bike.  The fork is just too dominant, wish your composition focussed more on the spectacular front wheel with the more interesting curves.</td>', 'Nice bike.  The fork is just too dominant, wish your composition focussed more on the spectacular front wheel with the more interesting curves.', '2006-04-12 15:53:26.000000', NULL, 1),
(2307504, 319600, 24454, '<td valign="top">Wow!  I don''t think chrome ever loooked so pretty.   I love how there are those pretty colored highlights in the shiny chrome. Fantastic job!!!!</td>', 'Wow!  I don''t think chrome ever loooked so pretty.   I love how there are those pretty colored highlights in the shiny chrome. Fantastic job!!!!', '2006-04-12 15:57:59.000000', NULL, 1),
(2307505, 319265, 44490, '<td valign="top">Nice composition.  Image looks grainy and overprocessed, the grain fights against the smooth shine of the chrome.</td>', 'Nice composition.  Image looks grainy and overprocessed, the grain fights against the smooth shine of the chrome.', '2006-04-12 15:58:32.000000', NULL, 1),
(2307506, 320047, 51538, '<td valign="top">Meets challange very well and is the only one to bring in a human side.</td>', 'Meets challange very well and is the only one to bring in a human side.', '2006-04-12 15:58:45.000000', NULL, 1),
(2307508, 318570, 51538, '<td valign="top">Nicely shot, stainless steel.  But voted highly since the spirit of chrome is reflective rather than chemical...</td>', 'Nicely shot, stainless steel.  But voted highly since the spirit of chrome is reflective rather than chemical...', '2006-04-12 15:59:23.000000', NULL, 1),
(2307512, 318553, 44490, '<td valign="top">You said it.  It''s hard to figure out what is going on here.  You might make voter stop for a few seconds more, but the end result will probably be a downgrade, as in this case.</td>', 'You said it.  It''s hard to figure out what is going on here.  You might make voter stop for a few seconds more, but the end result will probably be a downgrade, as in this case.', '2006-04-12 16:00:28.000000', NULL, 1),
(2307514, 319894, 51538, '<td valign="top">Nice inspiration.</td>', 'Nice inspiration.', '2006-04-12 16:00:46.000000', NULL, 1),
(2307515, 319989, 51538, '<td valign="top">A simple but elegant shot.</td>', 'A simple but elegant shot.', '2006-04-12 16:01:13.000000', NULL, 1),
(2307516, 319310, 33515, '<td valign="top">Nice colors and comp. Well done</td>', 'Nice colors and comp. Well done', '2006-04-12 16:02:19.000000', NULL, 1),
(2307519, 319387, 44490, '<td valign="top">Nice car and rack.  Less straight-on composition would be better, I think from slightly higher and behind, to show off the rack.  Also consider shallower DOF to blur out the background.  Looks like a lovely car.</td>', 'Nice car and rack.  Less straight-on composition would be better, I think from slightly higher and behind, to show off the rack.  Also consider shallower DOF to blur out the background.  Looks like a lovely car.', '2006-04-12 16:02:50.000000', NULL, 1),
(2307520, 319967, 44490, '<td valign="top">Striking image.  Probably better as a vertical, and wish for more chrome for this challenge.</td>', 'Striking image.  Probably better as a vertical, and wish for more chrome for this challenge.', '2006-04-12 16:04:05.000000', NULL, 1),
(2307522, 319463, 33515, '<td valign="top">Nice picture, I like the reflection on the side of the toaster. The folds in the back ground take away.</td>', 'Nice picture, I like the reflection on the side of the toaster. The folds in the back ground take away.', '2006-04-12 16:04:51.000000', NULL, 1),
(2307525, 317533, 33515, '<td valign="top">Good choice, I like the closeness of the lure.</td>', 'Good choice, I like the closeness of the lure.', '2006-04-12 16:05:45.000000', NULL, 1),
(2307526, 319638, 54571, '<td valign="top">Love the Caddy. The other car is distracting. You could have cropped it to exclude the Benz</td>', 'Love the Caddy. The other car is distracting. You could have cropped it to exclude the Benz', '2006-04-12 16:06:11.000000', NULL, 1),
(2307529, 318009, 33515, '<td valign="top">Nice picture, could have used more DOF to bring in the bullet light.</td>', 'Nice picture, could have used more DOF to bring in the bullet light.', '2006-04-12 16:06:41.000000', NULL, 1),
(2307532, 319720, 54571, '<td valign="top">Nice interpretation. Unique.</td>', 'Nice interpretation. Unique.', '2006-04-12 16:07:28.000000', NULL, 1),
(2307539, 319901, 44490, '<td valign="top">Nice shiny curve, nice composition.  With that title, how about some flowing water to finish it?</td>', 'Nice shiny curve, nice composition.  With that title, how about some flowing water to finish it?', '2006-04-12 16:09:48.000000', NULL, 1),
(2307540, 319835, 54571, '<td valign="top">Great shot. If the container had more shine it would be "greater".</td>', 'Great shot. If the container had more shine it would be "greater".', '2006-04-12 16:10:09.000000', NULL, 1),
(2307541, 319981, 51538, '<td valign="top">Refreshing.</td>', 'Refreshing.', '2006-04-12 16:10:28.000000', NULL, 1),
(2307543, 318735, 51538, '<td valign="top">Elegant.</td>', 'Elegant.', '2006-04-12 16:10:37.000000', NULL, 1),
(2307544, 317851, 54571, '<td valign="top">Geat interpretation.</td>', 'Geat interpretation.', '2006-04-12 16:11:00.000000', NULL, 1),
(2307546, 317533, 51538, '<td valign="top">Nice image.</td>', 'Nice image.', '2006-04-12 16:11:15.000000', NULL, 1),
(2307549, 319894, 54571, '<td valign="top">Love the "chrome" water effect.</td>', 'Love the "chrome" water effect.', '2006-04-12 16:12:27.000000', NULL, 1),
(2307552, 319676, 44490, '<td valign="top">Nice angle.  Clearer, more DOF, tighter crop out of right side with more hood-line on left might be better.</td>', 'Nice angle.  Clearer, more DOF, tighter crop out of right side with more hood-line on left might be better.', '2006-04-12 16:13:01.000000', NULL, 1),
(2307554, 319574, 44490, '<td valign="top">Nice curve, color, composition.  But what is it?  Wish I could figure it out so I could vote it higher.</td>', 'Nice curve, color, composition.  But what is it?  Wish I could figure it out so I could vote it higher.', '2006-04-12 16:14:43.000000', NULL, 1),
(2307557, 317533, 54571, '<td valign="top">Love the fish finder. A different background would have been more appealing to me.</td>', 'Love the fish finder. A different background would have been more appealing to me.', '2006-04-12 16:15:19.000000', NULL, 1),
(2307559, 319528, 54571, '<td valign="top">Great shot</td>', 'Great shot', '2006-04-12 16:16:32.000000', NULL, 1),
(2307561, 319886, 44490, '<td valign="top">Nice composition, shapes, lines.  Given a red bug, I think that a color pop would be appropriate, consider bumping up saturation, maybe levels.</td>', 'Nice composition, shapes, lines.  Given a red bug, I think that a color pop would be appropriate, consider bumping up saturation, maybe levels.', '2006-04-12 16:16:51.000000', NULL, 1),
(2307563, 319251, 54571, '<td valign="top">I like it. Very expressive.</td>', 'I like it. Very expressive.', '2006-04-12 16:17:28.000000', NULL, 1),
(2307576, 319698, 44490, '<td valign="top">Fascinating patterns in the chrome ball.  I think that more DOF would be better, and improve overall clarity.  I prefer less in-your-face out-of-focus foreground, and I think that this is a common preference.</td>', 'Fascinating patterns in the chrome ball.  I think that more DOF would be better, and improve overall clarity.  I prefer less in-your-face out-of-focus foreground, and I think that this is a common preference.', '2006-04-12 16:23:23.000000', NULL, 1),
(2307599, 319981, 44490, '<td valign="top">Nice composition, water, hand.  Wish for more visible chrome for this competition.  The stop motion is great.</td>', 'Nice composition, water, hand.  Wish for more visible chrome for this competition.  The stop motion is great.', '2006-04-12 16:33:21.000000', NULL, 1),
(2307601, 316960, 45651, '<td valign="top">This would be bronze I think.</td>', 'This would be bronze I think.', '2006-04-12 16:33:40.000000', NULL, 1),
(2307603, 317851, 44490, '<td valign="top">Nice nostalgia!  More DOF would be better in my opinion, and consider brighter levels and more saturation for color pop, probably better than subtlety for this subject.</td>', 'Nice nostalgia!  More DOF would be better in my opinion, and consider brighter levels and more saturation for color pop, probably better than subtlety for this subject.', '2006-04-12 16:34:11.000000', NULL, 1),
(2307606, 317851, 45651, '<td valign="top">Nice play on words.</td>', 'Nice play on words.', '2006-04-12 16:35:30.000000', NULL, 1),
(2307624, 319726, 44490, '<td valign="top">Nice composition, nice shiny hydrants.  Wish for just a touch more DOF, maybe a touch more headroom / less crop at top.</td>', 'Nice composition, nice shiny hydrants.  Wish for just a touch more DOF, maybe a touch more headroom / less crop at top.', '2006-04-12 16:41:45.000000', NULL, 1),
(2307631, 318215, 57000, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2006-04-12 16:45:39.000000', NULL, 1),
(2307633, 318715, 57000, '<td valign="top">Very good wideangle.</td>', 'Very good wideangle.', '2006-04-12 16:46:53.000000', NULL, 1),
(2307643, 319407, 44490, '<td valign="top">Nice idea and execution.  Too bad it looks oversharpened to me, so much that the sharper curves have turned jagged.  Great idea and capture, just too much processing.</td>', 'Nice idea and execution.  Too bad it looks oversharpened to me, so much that the sharper curves have turned jagged.  Great idea and capture, just too much processing.', '2006-04-12 16:52:08.000000', NULL, 1),
(2307644, 317035, 44490, '<td valign="top">Nice composition for the bike.  The background is distracting, did you try opening up to blur it out?  Wish you had advanced editing to eliminate the blue line, maybe yellow sign.  The bike is wonderful.</td>', 'Nice composition for the bike.  The background is distracting, did you try opening up to blur it out?  Wish you had advanced editing to eliminate the blue line, maybe yellow sign.  The bike is wonderful.', '2006-04-12 16:52:31.000000', NULL, 1),
(2307647, 319309, 44490, '<td valign="top">Ah for those rocket fins from the late 50''s (Caddys)!  Nice composition, wish there were no house roofline, more illumination and more shiny chrome, but showing the age is appropriate.  Nice nostalgia.</td>', 'Ah for those rocket fins from the late 50''s (Caddys)!  Nice composition, wish there were no house roofline, more illumination and more shiny chrome, but showing the age is appropriate.  Nice nostalgia.', '2006-04-12 16:53:13.000000', NULL, 1),
(2307649, 319953, 44490, '<td valign="top">Nice composition, contrast of metal surfaces, shiny, painted, rusted.  Wish for slightly brighter levels.</td>', 'Nice composition, contrast of metal surfaces, shiny, painted, rusted.  Wish for slightly brighter levels.', '2006-04-12 16:53:37.000000', NULL, 1),
(2307691, 320006, 31133, '<td valign="top">Clever shot and quite a different take than the average. The only niggle I have is the black spot on the shower head, but maybe you wanted it there. I like the angle a lot. Also like the looks of the shower head cord and the water spray.</td>', 'Clever shot and quite a different take than the average. The only niggle I have is the black spot on the shower head, but maybe you wanted it there. I like the angle a lot. Also like the looks of the shower head cord and the water spray.', '2006-04-12 17:13:56.000000', NULL, 1),
(2307696, 319506, 31133, '<td valign="top">It''s chrome and meets the challenge, but for me the interesting part is where the strings wrap around the tuning pegs. The rest of the shot, for me, takes away from the "wow" factor. I really like the bottom half a lot, though, especially the lighting and the shadows of the strings.</td>', 'It''s chrome and meets the challenge, but for me the interesting part is where the strings wrap around the tuning pegs. The rest of the shot, for me, takes away from the "wow" factor. I really like the bottom half a lot, though, especially the lighting and the shadows of the strings.', '2006-04-12 17:16:04.000000', NULL, 1),
(2307703, 320006, 44490, '<td valign="top">Interesting composition, water.  Very effective use of curve inversion.  Striking and fascinating.</td>', 'Interesting composition, water.  Very effective use of curve inversion.  Striking and fascinating.', '2006-04-12 17:18:28.000000', NULL, 1),
(2307705, 319773, 44490, '<td valign="top">Very nice composition, interesting mix of smooth curves and sharp-angled handles.  Love the high-contrast shapes, wish for more chrome for this challenge.</td>', 'Very nice composition, interesting mix of smooth curves and sharp-angled handles.  Love the high-contrast shapes, wish for more chrome for this challenge.', '2006-04-12 17:19:00.000000', NULL, 1),
(2307708, 319981, 33515, '<td valign="top">Because the image was rotated 90 it seems to add more confusion than anything else. I like the photo, especially the drips off the fingers.</td>', 'Because the image was rotated 90 it seems to add more confusion than anything else. I like the photo, especially the drips off the fingers.', '2006-04-12 17:19:03.000000', NULL, 1),
(2307709, 319639, 44490, '<td valign="top">Nice composition, sharpness, clarity.  Please consider toning down the orange, it steals attention away from your chrome subject.</td>', 'Nice composition, sharpness, clarity.  Please consider toning down the orange, it steals attention away from your chrome subject.', '2006-04-12 17:19:13.000000', NULL, 1),
(2307710, 319080, 31133, '<td valign="top">I love rusty and colorful old car shots! A bit blown at the front part of the fender, but it doesn''t detract too much. The colors are great. The headlight is  also a really strong positive in this image - it looks so cool.</td>', 'I love rusty and colorful old car shots! A bit blown at the front part of the fender, but it doesn''t detract too much. The colors are great. The headlight is  also a really strong positive in this image - it looks so cool.', '2006-04-12 17:19:14.000000', NULL, 1),
(2307715, 319217, 44490, '<td valign="top">Very nice composition, colors, combination with glass.  Wonderful, and hope it does well</td>', 'Very nice composition, colors, combination with glass.  Wonderful, and hope it does well', '2006-04-12 17:19:54.000000', NULL, 1),
(2307716, 317834, 44490, '<td valign="top">Very nice composition, plenty of shine and reflections, good DOF to isolate foreground.  Wonderful, love it.</td>', 'Very nice composition, plenty of shine and reflections, good DOF to isolate foreground.  Wonderful, love it.', '2006-04-12 17:19:57.000000', NULL, 1),
(2307718, 318960, 33515, '<td valign="top">The DOF seems to be to shallow to really high lite the surface.</td>', 'The DOF seems to be to shallow to really high lite the surface.', '2006-04-12 17:20:14.000000', NULL, 1),
(2307721, 319348, 31133, '<td valign="top">Meets the challenge, but the focus suffers and small pictures are never favorites with we picky, picky voters. Sorry. If this could be a bit bigger and more in focus, I think it could be a contender.</td>', 'Meets the challenge, but the focus suffers and small pictures are never favorites with we picky, picky voters. Sorry. If this could be a bit bigger and more in focus, I think it could be a contender.', '2006-04-12 17:20:30.000000', NULL, 1),
(2307722, 319801, 44490, '<td valign="top">Mix of regular and extreme draws another look.  Strangely puzzling and effective.  Well done.</td>', 'Mix of regular and extreme draws another look.  Strangely puzzling and effective.  Well done.', '2006-04-12 17:20:34.000000', NULL, 1),
(2307723, 319920, 44490, '<td valign="top">Fascinating water path, I hope that other people caught it as well.  Nice composition, stop motion, colors in faucet head, light in droplets transitioning with nice bokeh.  Wonderful.</td>', 'Fascinating water path, I hope that other people caught it as well.  Nice composition, stop motion, colors in faucet head, light in droplets transitioning with nice bokeh.  Wonderful.', '2006-04-12 17:20:42.000000', NULL, 1),
(2307724, 319834, 44490, '<td valign="top">Nice combination of new and old woodys -- I hope that people don''t miss the new woody, as I missed it on the first viewing.  Very interesting, nicely done.</td>', 'Nice combination of new and old woodys -- I hope that people don''t miss the new woody, as I missed it on the first viewing.  Very interesting, nicely done.', '2006-04-12 17:20:52.000000', NULL, 1),
(2307725, 319463, 44490, '<td valign="top">Nice additional elements to toaster, effectively incorporating action and a story.  Simple, effective, well done. :-)</td>', 'Nice additional elements to toaster, effectively incorporating action and a story.  Simple, effective, well done. :-)', '2006-04-12 17:20:55.000000', NULL, 1),
(2307726, 319109, 44490, '<td valign="top">Nice capture, composition, DOF.  Love the snow, the image, and the story.  Very nice.</td>', 'Nice capture, composition, DOF.  Love the snow, the image, and the story.  Very nice.', '2006-04-12 17:21:04.000000', NULL, 1),
(2307727, 319080, 44490, '<td valign="top">Nice composition, colors, contrast of chrome, paint, and rust.  Tells a story, I like it a lot, and it gets better with viewing.</td>', 'Nice composition, colors, contrast of chrome, paint, and rust.  Tells a story, I like it a lot, and it gets better with viewing.', '2006-04-12 17:21:08.000000', NULL, 1),
(2307728, 318182, 44490, '<td valign="top">Nice composition and colors.  Nice engine, just beatiful, probably from any angle.</td>', 'Nice composition and colors.  Nice engine, just beatiful, probably from any angle.', '2006-04-12 17:21:13.000000', NULL, 1),
(2307732, 319524, 31133, '<td valign="top">Wow, now this is an interesting entry! Very nice effects and careful processing. The shine is captivating. I feel like I''d like to see this sharper, but maybe the softness is part of the intention here. Everything goes together well, colors, frame, and composition, like a piece of music. Nice.</td>', 'Wow, now this is an interesting entry! Very nice effects and careful processing. The shine is captivating. I feel like I''d like to see this sharper, but maybe the softness is part of the intention here. Everything goes together well, colors, frame, and composition, like a piece of music. Nice.', '2006-04-12 17:23:06.000000', NULL, 1),
(2307737, 319217, 31133, '<td valign="top">This reminds me of music. I don''t know why - maybe because another shot made me think of music, and this one popped up immediately after. Maybe it''s because of the verticals in the glass and horizontals in the steps, with the chrome sliding up diagonally. Don''t know, but I think I do know who made this image :-) and I like it a lot. Good job; I hope you do well! The light in the left is really the icing on the cake - nice.</td>', 'This reminds me of music. I don''t know why - maybe because another shot made me think of music, and this one popped up immediately after. Maybe it''s because of the verticals in the glass and horizontals in the steps, with the chrome sliding up diagonally. Don''t know, but I think I do know who made this image :-) and I like it a lot. Good job; I hope you do well! The light in the left is really the icing on the cake - nice.', '2006-04-12 17:26:04.000000', NULL, 1),
(2307745, 319993, 31133, '<td valign="top">This is a little hard for me to figure out. I like the title, but I wish I could see or understand where the chrome is. I try to not vote down for lack of meeting the challenge, in case I''m missing something that I should see. However, for the image itself, I am voting down a little because of the focus and other technicalities. The background would benefit from being much more out of focus, so the eye is drawn to focus on the bird. The bird is really cute.</td>', 'This is a little hard for me to figure out. I like the title, but I wish I could see or understand where the chrome is. I try to not vote down for lack of meeting the challenge, in case I''m missing something that I should see. However, for the image itself, I am voting down a little because of the focus and other technicalities. The background would benefit from being much more out of focus, so the eye is drawn to focus on the bird. The bird is really cute.', '2006-04-12 17:29:42.000000', NULL, 1),
(2307751, 319886, 31133, '<td valign="top">Not being especially into cars, I had no idea how beautiful the curves of a ''68 bug were until now! The chrome doesn''t interest me here at all as much as that fantastic read swirl of the body ... very nice entry.</td>', 'Not being especially into cars, I had no idea how beautiful the curves of a ''68 bug were until now! The chrome doesn''t interest me here at all as much as that fantastic read swirl of the body ... very nice entry.', '2006-04-12 17:31:22.000000', NULL, 1),
(2307753, 317194, 31133, '<td valign="top">This meets the challenge well, in my opinion, but I wish it had a bit more to it, maybe color or focus or a little off-centering of the subject. The strongest aspect of this for me is the handle, which I think came out really nicely. It''s sharp and has an interesting shape.</td>', 'This meets the challenge well, in my opinion, but I wish it had a bit more to it, maybe color or focus or a little off-centering of the subject. The strongest aspect of this for me is the handle, which I think came out really nicely. It''s sharp and has an interesting shape.', '2006-04-12 17:33:37.000000', NULL, 1),
(2307758, 319639, 31133, '<td valign="top">I mentioned in another entry that I love, love old rusty car shots. Even though this car doesn''t look rusty, the quality is the same - old and beautiful. I would never guess that these two color combinations, red and purple-magenta, would look nice together - but they do! I think the red sets of the the car in an interesting way. Love the fact that the car is wet - that adds a lot to this!</td>', 'I mentioned in another entry that I love, love old rusty car shots. Even though this car doesn''t look rusty, the quality is the same - old and beautiful. I would never guess that these two color combinations, red and purple-magenta, would look nice together - but they do! I think the red sets of the the car in an interesting way. Love the fact that the car is wet - that adds a lot to this!', '2006-04-12 17:36:25.000000', NULL, 1),
(2307760, 318592, 31133, '<td valign="top">Beautiful composition!! It would be awesome if it used the whole 640 pixels allowed. Actually, it would be awesome as an even larger image - bet it makes a great print. Congratulations on a very good image.</td>', 'Beautiful composition!! It would be awesome if it used the whole 640 pixels allowed. Actually, it would be awesome as an even larger image - bet it makes a great print. Congratulations on a very good image.', '2006-04-12 17:38:09.000000', NULL, 1),
(2307763, 319521, 31133, '<td valign="top">The composition is interesting and eye-catching, but the blow-outs detract for me. Sorry. Otherwise, I think the technicals are fine, with the focus and I like the abstract crop.</td>', 'The composition is interesting and eye-catching, but the blow-outs detract for me. Sorry. Otherwise, I think the technicals are fine, with the focus and I like the abstract crop.', '2006-04-12 17:41:24.000000', NULL, 1),
(2307766, 319385, 31133, '<td valign="top">Heh, heh! Cute. Poor Adam looks squished :-)</td>', 'Heh, heh! Cute. Poor Adam looks squished :-)', '2006-04-12 17:42:16.000000', NULL, 1),
(2307768, 319159, 31133, '<td valign="top">Looks like a good product shot. Maybe a bit on the glary side, light is a tad harsh, but I can easily imagine this in a product catalog.</td>', 'Looks like a good product shot. Maybe a bit on the glary side, light is a tad harsh, but I can easily imagine this in a product catalog.', '2006-04-12 17:43:40.000000', NULL, 1),
(2307780, 319963, 31133, '<td valign="top">Love the title! I like this a lot, but wish the background was more blurred, since the eye is drawn away from the lights due to the strong lines and colors of the background.</td>', 'Love the title! I like this a lot, but wish the background was more blurred, since the eye is drawn away from the lights due to the strong lines and colors of the background.', '2006-04-12 17:47:22.000000', NULL, 1),
