(2309059, 319348, 56579, '<td valign="top">your subject is not very intresting.  Your photo size could be larger.  Also looks like it could use some colour/saturation adjusting.</td>', 'your subject is not very intresting.  Your photo size could be larger.  Also looks like it could use some colour/saturation adjusting.', '2006-04-13 01:33:14.000000', NULL, 1),
(2309060, 320026, 56579, '<td valign="top">your subject is not very intresting....infact I am not even sure what the subject is.  Ether your photo is blury or your depth of field is too shallow.  I recomend using a smaller apature (larger fstop).</td>', 'your subject is not very intresting....infact I am not even sure what the subject is.  Ether your photo is blury or your depth of field is too shallow.  I recomend using a smaller apature (larger fstop).', '2006-04-13 01:34:25.000000', NULL, 1),
(2309123, 320058, 41574, '<td valign="top">"Reflections"? I can see barely a thing.</td>', '"Reflections"? I can see barely a thing.', '2006-04-13 02:02:47.000000', NULL, 1),
(2309125, 320047, 41574, '<td valign="top">"Terminator" reference? Instant high-score. :-D!</td>', '"Terminator" reference? Instant high-score. :-D!', '2006-04-13 02:03:07.000000', NULL, 1),
(2309203, 319967, 56752, '<td valign="top">Patriotic idea, but honestly the pole is much too flat for what I consider to be ''chrome''</td>', 'Patriotic idea, but honestly the pole is much too flat for what I consider to be ''chrome''', '2006-04-13 02:25:52.000000', NULL, 1),
(2309209, 319901, 56752, '<td valign="top">Good shot, but it just looks a littttttle too dull contrast-wise to my eyes</td>', 'Good shot, but it just looks a littttttle too dull contrast-wise to my eyes', '2006-04-13 02:27:16.000000', NULL, 1),
(2309223, 320012, 56752, '<td valign="top">This would have been really nice if there was a bit more DOF. The blurred background is nice with the flag, but the fact that the foreground from the center to the right is out of focus as well doesn''t do the image any favors. As it stands, a good image, but not quite a great one.</td>', 'This would have been really nice if there was a bit more DOF. The blurred background is nice with the flag, but the fact that the foreground from the center to the right is out of focus as well doesn''t do the image any favors. As it stands, a good image, but not quite a great one.', '2006-04-13 02:30:32.000000', NULL, 1),
(2309228, 319109, 56752, '<td valign="top">Great framing, subject, shot, everything.</td>', 'Great framing, subject, shot, everything.', '2006-04-13 02:31:01.000000', NULL, 1),
(2309238, 319912, 56752, '<td valign="top">To be honest, it''s tough to figure out what''s going on in this image, and the quality could stand to be improved.</td>', 'To be honest, it''s tough to figure out what''s going on in this image, and the quality could stand to be improved.', '2006-04-13 02:33:00.000000', NULL, 1),
(2309256, 318215, 56752, '<td valign="top">Amazing picture that while lacking a great deal of chrome, what IS there is very effective. Must be some coating on that bumper!</td>', 'Amazing picture that while lacking a great deal of chrome, what IS there is very effective. Must be some coating on that bumper!', '2006-04-13 02:38:05.000000', NULL, 1),
