(2309707, 318182, 42100, '<td valign="top">Great photo with the blue paint reflecting on all that chrome.  Very nice!</td>', 'Great photo with the blue paint reflecting on all that chrome.  Very nice!', '2006-04-13 10:27:00.000000', NULL, 1),
(2309711, 319310, 42100, '<td valign="top">Interesting shape and form to this photo, and well composed also.  Very nice!</td>', 'Interesting shape and form to this photo, and well composed also.  Very nice!', '2006-04-13 10:31:36.000000', NULL, 1),
(2309717, 319071, 42100, '<td valign="top">I like how the red lights reflect all over the skull.  Cool photo!</td>', 'I like how the red lights reflect all over the skull.  Cool photo!', '2006-04-13 10:34:00.000000', NULL, 1),
(2309720, 317198, 53463, '<td valign="top">clever</td>', 'clever', '2006-04-13 10:35:40.000000', NULL, 1),
