(2310328, 319886, 33515, '<td valign="top">Nice crop, to bad about the rust, not for your picture but for the car. 7</td>', 'Nice crop, to bad about the rust, not for your picture but for the car. 7', '2006-04-13 15:36:10.000000', NULL, 1),
(2310335, 318746, 33515, '<td valign="top">The idea is solid but I feel it could have been better if you had used a white sheet above the tools and avoided the black lines. 7</td>', 'The idea is solid but I feel it could have been better if you had used a white sheet above the tools and avoided the black lines. 7', '2006-04-13 15:38:03.000000', NULL, 1),
(2310388, 317358, 35513, '<td valign="top">I like the composition of this shot a lot, but I find the nozzle for the tire (on the right) to be a little distracting.  The lighting shows the chrome off well!</td>', 'I like the composition of this shot a lot, but I find the nozzle for the tire (on the right) to be a little distracting.  The lighting shows the chrome off well!', '2006-04-13 15:59:31.000000', NULL, 1),
(2310389, 319574, 35513, '<td valign="top">Very abstract, but I really like the coloring!</td>', 'Very abstract, but I really like the coloring!', '2006-04-13 15:59:53.000000', NULL, 1),
(2310392, 319666, 35513, '<td valign="top">The lighting gives a really nice depth to this shot!</td>', 'The lighting gives a really nice depth to this shot!', '2006-04-13 16:01:08.000000', NULL, 1),
(2310396, 317860, 35513, '<td valign="top">Very creative idea!</td>', 'Very creative idea!', '2006-04-13 16:02:55.000000', NULL, 1),
(2310399, 319894, 35513, '<td valign="top">The ripples in the water really make this shot stand out!</td>', 'The ripples in the water really make this shot stand out!', '2006-04-13 16:03:19.000000', NULL, 1),
(2310408, 318322, 35513, '<td valign="top">I really like the composition here, especially with the folds in the fabric.  The reflection in the metal is a little distracting, but other than that, you''re spot on!  The lighting really brings out some nice tones in this photo.</td>', 'I really like the composition here, especially with the folds in the fabric.  The reflection in the metal is a little distracting, but other than that, you''re spot on!  The lighting really brings out some nice tones in this photo.', '2006-04-13 16:07:04.000000', NULL, 1),
(2310411, 319528, 33515, '<td valign="top">Nice shot, lots of chrome and no annoying reflections from the back ground. Bump to 9</td>', 'Nice shot, lots of chrome and no annoying reflections from the back ground. Bump to 9', '2006-04-13 16:07:47.000000', NULL, 1),
(2310412, 317198, 35513, '<td valign="top">Very creative subject choice!</td>', 'Very creative subject choice!', '2006-04-13 16:08:45.000000', NULL, 1),
(2310482, 319348, 43565, '<td valign="top">This does not hold my interest and I think it could be more in focus.</td>', 'This does not hold my interest and I think it could be more in focus.', '2006-04-13 17:01:01.000000', NULL, 1),
(2310483, 320026, 43565, '<td valign="top">I think the focus could be better and it does not hold my interest.</td>', 'I think the focus could be better and it does not hold my interest.', '2006-04-13 17:01:40.000000', NULL, 1),
(2310487, 316960, 43565, '<td valign="top">Is this a chrome statue?  I find the background distracting.  Taking it from another direction, or useing a blurring filter on the background might help.</td>', 'Is this a chrome statue?  I find the background distracting.  Taking it from another direction, or useing a blurring filter on the background might help.', '2006-04-13 17:04:07.000000', NULL, 1),
(2310489, 318511, 43565, '<td valign="top">I think greater DOF would have helped this.</td>', 'I think greater DOF would have helped this.', '2006-04-13 17:04:30.000000', NULL, 1),
