(2310493, 318308, 43565, '<td valign="top">Not sure what this is (scratched CD?).  Maybe if the scratches were in focus I would like it better.  I also find the arc of red and green distracting.</td>', 'Not sure what this is (scratched CD?).  Maybe if the scratches were in focus I would like it better.  I also find the arc of red and green distracting.', '2006-04-13 17:06:05.000000', NULL, 1),
(2310494, 318592, 43565, '<td valign="top">Not sure what this is or it it is chrome.</td>', 'Not sure what this is or it it is chrome.', '2006-04-13 17:06:12.000000', NULL, 1),
(2310496, 319655, 43565, '<td valign="top">The background is so busy that the charms get lost.  They are the last thing I notice, and yet are the subject of the shot.</td>', 'The background is so busy that the charms get lost.  They are the last thing I notice, and yet are the subject of the shot.', '2006-04-13 17:08:07.000000', NULL, 1),
(2310499, 319835, 32644, '<td valign="top">Nice shot but finger prints and water spots detract.</td>', 'Nice shot but finger prints and water spots detract.', '2006-04-13 17:09:01.000000', NULL, 1),
(2310501, 319546, 43565, '<td valign="top">Try to resize to the 640 allowed.  My eye goes to the patch of sunlight instead of the the chrome wheel.</td>', 'Try to resize to the 640 allowed.  My eye goes to the patch of sunlight instead of the the chrome wheel.', '2006-04-13 17:09:44.000000', NULL, 1),
(2310502, 319639, 42132, '<td valign="top">great colours,fantastic car.like the way you''ve cropped this too.</td>', 'great colours,fantastic car.like the way you''ve cropped this too.', '2006-04-13 17:09:49.000000', NULL, 1),
