(2310634, 319147, 55881, '<td valign="top">Hehe! nice interesting shot!</td>', 'Hehe! nice interesting shot!', '2006-04-13 18:13:33.000000', NULL, 1),
(2310658, 320047, 55546, '<td valign="top">very nice concept...well executed, taking into account the "hot" subject - i just hope this is not a process-created effect<br/> <br/>because i believe in the inherent goodness of humanity (some call this naivety), you get an "elightening 8" from me for this attempt<br/> <br/>please let publish your workflow, and it will also be interesting to know who this image is of<br/> <br/>good luck</td>', 'very nice concept...well executed, taking into account the "hot" subject - i just hope this is not a process-created effect because i believe in the inherent goodness of humanity (some call this naivety), you get an "elightening 8" from me for this attempt please let publish your workflow, and it will also be interesting to know who this image is of good luck', '2006-04-13 18:28:31.000000', NULL, 1),
