(2310762, 320047, 36988, '<td valign="top">Very unique and perfectly original. Not much to complain about here and my choice for top honors... well done!</td>', 'Very unique and perfectly original. Not much to complain about here and my choice for top honors... well done!', '2006-04-13 19:21:21.000000', NULL, 1),
