(2310901, 319423, 42013, '<td valign="top">Entertaining and Informative :)</td>', 'Entertaining and Informative :)', '2006-04-13 20:46:18.000000', NULL, 1),
(2310916, 319407, 42013, '<td valign="top">This is a great idea. the amount of chrome is startling and the reflected harley is pretty cool. It seems as though there is an odd speckled pattern on some of the chrome areas.  Not sure if it is pixelation or maybe a filter. Takes away some of the smoothness of the pic IMHO.</td>', 'This is a great idea. the amount of chrome is startling and the reflected harley is pretty cool. It seems as though there is an odd speckled pattern on some of the chrome areas.  Not sure if it is pixelation or maybe a filter. Takes away some of the smoothness of the pic IMHO.', '2006-04-13 20:57:59.000000', NULL, 1),
(2310919, 317851, 42013, '<td valign="top">Points for out of the box thinking :)</td>', 'Points for out of the box thinking :)', '2006-04-13 20:59:02.000000', NULL, 1),
