(2321663, 317356, 4010, '<td valign="top">Like the use of the reflective nature of chrome surfaces.  I think this is the key to a good shot in this challenge.  Well done.</td>', 'Like the use of the reflective nature of chrome surfaces.  I think this is the key to a good shot in this challenge.  Well done.', '2006-04-18 11:47:18.000000', NULL, 1),
